// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-nav-drawer.js';
import './md-gb-nav-drawer-item.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The index of the item that holds focus (also inside its shadow root), or -1. */
function focusedIndex(items: Element[]) {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return items.findIndex((item) => path.some((e) => e === item || item.contains(e)));
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: {items: HTMLElement[]}, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: {dir?: string; disabled?: number} = {}) {
  const root = await mount(html`
    <button id="before">Before</button>
    <div dir=${opts.dir ?? 'ltr'}>
      <md-gb-nav-drawer open aria-label="Mail">
      <md-gb-nav-drawer-item>Alpha</md-gb-nav-drawer-item>
      <md-gb-nav-drawer-item>Bravo</md-gb-nav-drawer-item>
      <md-gb-nav-drawer-item>Charlie</md-gb-nav-drawer-item>
      <md-gb-nav-drawer-item>Delta</md-gb-nav-drawer-item>
      </md-gb-nav-drawer>
    </div>
    <button id="after">After</button>
  `);
  const items = [...root.querySelectorAll<HTMLElement>('md-gb-nav-drawer-item')];
  if (opts.disabled !== undefined) {
    items[opts.disabled].setAttribute('disabled', '');
    await settle();
  }
  return {
    group: root.querySelector<HTMLElement>('md-gb-nav-drawer')!,
    items,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

describe('<md-gb-nav-drawer> roving focus contract (RovingFocusController: vertical, wrap, Home/End, one tab stop)', () => {
  afterEach(() => container?.remove());

  it('is entered with Tab on the first item; the container takes no focus', async () => {
    // spec: navigation-drawer-054d25, navigation-drawer-b59187, navigation-drawer-e712cc
    const f = await setup();
    f.before.focus();
    await press('Tab');
    expect(focusedIndex(f.items)).toBe(0);
    expect(f.group.matches(':focus')).toBeFalse();
  });

  it('moves focus to the next and previous item with ArrowDown / ArrowUp', async () => {
    // spec: navigation-drawer-943104, navigation-drawer-75bcc7
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowDown');
    expect(focusedIndex(f.items)).toBe(2);
    await press('ArrowUp');
    await press('ArrowUp');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('does not move focus with ArrowRight (vertical only)', async () => {
    // spec: navigation-drawer-943104, navigation-drawer-75bcc7
    const f = await setup();
    await focusItem(f, 1);
    await press('ArrowRight');
    expect(focusedIndex(f.items)).toBe(1);
  });

  it('wraps from the last item to the first and back', async () => {
    // spec: navigation-drawer-943104, navigation-drawer-75bcc7
    const f = await setup();
    await focusItem(f, -1);
    await press('ArrowDown');
    expect(focusedIndex(f.items)).toBe(0);
    await press('ArrowUp');
    expect(focusedIndex(f.items)).toBe(f.items.length - 1);
  });

  it('moves to the first and last item with Home and End', async () => {
    const f = await setup();
    await focusItem(f, 1);
    await press('End');
    expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    await press('Home');
    expect(focusedIndex(f.items)).toBe(0);
  });

  it('skips disabled items', async () => {
    const f = await setup({disabled: 1});
    await focusItem(f, 0);
    await press('ArrowDown');
    expect(focusedIndex(f.items)).toBe(2);
  });

  it('is one tab stop that remembers the last focused item', async () => {
    const f = await setup();
    await focusItem(f, 0);
    await press('ArrowDown');
    await press('ArrowDown');
    await press('Tab');
    expect(document.activeElement).toBe(f.after);
    await press('Shift+Tab');
    expect(focusedIndex(f.items)).toBe(2);
  });
});

/** Dispatches a pointer event with a given `timeStamp` (ms). */
function dsPointer(target: EventTarget, type: string, x: number, y: number, time: number) {
  const event = new PointerEvent(type, {
    bubbles: true,
    composed: true,
    cancelable: true,
    pointerId: 7,
    pointerType: 'touch',
    isPrimary: true,
    button: 0,
    clientX: x,
    clientY: y,
  });
  Object.defineProperty(event, 'timeStamp', {value: time});
  target.dispatchEvent(event);
}

function dsCenter(element: Element) {
  const rect = element.getBoundingClientRect();
  return {x: rect.left + rect.width / 2, y: rect.top + rect.height / 2};
}

/**
 * Presses the center of `target`, moves `dx` along x in `steps` moves and
 * releases (axis y moves along y instead). Slow by default (50ms per step); `fast` flings (2ms per step).
 */
function dsDrag(
  target: Element,
  dx: number,
  {release = true, fast = false, steps = 4, axis = 'x'}: {release?: boolean; fast?: boolean; steps?: number; axis?: 'x' | 'y'} = {},
) {
  const {x, y} = dsCenter(target);
  const ms = fast ? 2 : 50;
  dsPointer(target, 'pointerdown', x, y, 0);
  for (let i = 1; i <= steps; i++) {
    const d = (dx * i) / steps;
    dsPointer(target, 'pointermove', axis === 'y' ? x : x + d, axis === 'y' ? y + d : y, ms * i);
  }
  if (release) dsPointer(target, 'pointerup', axis === 'y' ? x : x + dx, axis === 'y' ? y + dx : y, ms * steps + (fast ? 0 : 500));
}

let dsTokens = false;
const dsExtra: HTMLElement[] = [];

/** Adopts the M3 tokens (once) so motion tokens and component styles resolve. */
async function dsLoadTokens() {
  if (dsTokens) return;
  dsTokens = true;
  const [{adoptStyles}, {styles}] = await Promise.all([
    import('../../styles/adopt-styles.js'),
    import('../../styles/m3.cssresult.js'),
  ]);
  adoptStyles(document, [styles]);
}

async function dsMount(markup: string, selector: string) {
  await dsLoadTokens();
  const host = document.createElement('div');
  host.innerHTML = markup;
  document.body.appendChild(host);
  await settle();
  dsExtra.push(host);
  return host.querySelector<HTMLElement>(selector)!;
}
void dsMount; // Not every component uses it.

async function dsSetup(template: TemplateResult, selector: string) {
  await dsLoadTokens();
  const root = await mount(template);

  const el = root.querySelector<HTMLElement>(selector)! as HTMLElement & {expanded: boolean; open: boolean; revealed: string | null; items: HTMLElement[]; paneWidth: number | null; collapsedPane: string | null; state: string; selectedIndex: number; panels: HTMLElement[]; show(): Promise<void>};
  return {root, el};
}

/** Runs `fn` with reduced motion preferred, then restores the preference. */
async function dsReduceMotion(fn: () => Promise<void>) {
  const {emulateMedia} = await import('@web/test-runner-commands');
  await emulateMedia({reducedMotion: 'reduce'});
  try {
    await fn();
  } finally {
    await emulateMedia({reducedMotion: 'no-preference'});
  }
}


